mapper.select:
SELECT d.dept_code AS deptCode, d.dept_name AS deptName, SUM(NVL(total_visits, 0)) AS totalVisits, SUM(NVL(famous_expert, 0)) AS famousExpert, SUM(NVL(special_expert, 0)) AS specialExpert, SUM(NVL(known_expert, 0)) AS knownExpert, SUM(NVL(expert_a, 0)) AS expertA, SUM(NVL(expert_b, 0)) AS expertB, SUM(NVL(ordinary, 0)) AS ordinary, SUM(NVL(unit_famous_effective, 0)) AS unitFamousEffective, SUM(NVL(unit_famous_total, 0)) AS unitFamousTotal, SUM(NVL(unit_special_effective, 0)) AS unitSpecialEffective, SUM(NVL(unit_special_total, 0)) AS unitSpecialTotal, SUM(NVL(unit_known_effective, 0)) AS unitKnownEffective, SUM(NVL(unit_known_total, 0)) AS unitKnownTotal, SUM(NVL(unit_a_effective, 0)) AS unitAEffective, SUM(NVL(unit_a_total, 0)) AS unitATotal, SUM(NVL(unit_b_effective, 0)) AS unitBEffective, SUM(NVL(unit_b_total, 0)) AS unitBTotal, SUM(NVL(unit_ordinary_effective, 0)) AS unitOrdinaryEffective, SUM(NVL(unit_ordinary_total, 0)) AS unitOrdinaryTotal, SUM(NVL(appointment_total, 0)) AS appointmentTotal, SUM(NVL(appointment_count, 0)) AS appointmentCount, SUM(NVL(return_visits, 0)) AS returnVisits, SUM(NVL(treat_count, 0)) AS treatCount, MAX(unit) AS unit FROM TR_OUTP_OP a LEFT JOIN TR_DEPT_DICT d ON a.dept_code = d.dept_code WHERE stat_date BETWEEN #{startDate} AND #{endDate}
AND d.dept_code = #{deptCode}
GROUP BY d.dept_code, d.dept_name ORDER BY totalVisits DESC

SELECT stat_date AS statDate, d.dept_name AS deptName, d.dept_code AS deptCode, visits, appointment_rate AS appointmentRate, exam_rate AS examRate, efficiency, visit_count AS visitCount, famous_expert AS famousExpert, special_expert AS specialExpert, known_expert AS knownExpert, expert_a AS expertA, expert_b AS expertB, ordinary, effective_total AS effectiveTotal, effective_detail AS effectiveDetail, total_detail AS totalDetail FROM TR_OUTP_OP_DTL a LEFT JOIN TR_DEPT_DICT d ON a.dept_code = d.dept_code WHERE stat_date BETWEEN #{startDate} AND #{endDate}
AND d.dept_code = #{deptCode}
AND d.dept_name LIKE '%' || #{deptName} || '%'
ORDER BY d.dept_code
